import React, { useEffect, useRef, useState } from "react";
import Button from "../../common/button";

import ActiveIcon from "../../assets/images/icons/iconAction.svg";
import Search from "../../assets/images/icons/SearchIcon.svg";
import clearFilter from "../../assets/images/icons/Clear-Filter-Icon-White.svg";
import shorting from "../../assets/images/icons/shorting.svg";
import AddItem from "../../assets/images/icons/addItem.svg";
import Grid from "../../common/grid";
import Input from "../../common/input";
import Cross from "../../assets/images/Cross.png";
import DataTable from "react-data-table-component";
import {
  getDealerPricebookDetailById,
  getTermList,
} from "../../services/dealerServices";
import { getCategoryList, getCovrageList } from "../../services/priceBookService";
import { Link, useNavigate, useParams } from "react-router-dom";
import { useFormik } from "formik";
import * as Yup from "yup";
import Select from "../../common/select";
import { RotateLoader } from "react-spinners";

import Modal from "../../common/model";
import { getPriceBookListByResellerId } from "../../services/reSellerServices";
import Headbar from "../../common/headBar";
import view from "../../assets/images/eye.png";
import {
  getPriceBookDetailsForDealerPortal,
  getPriceBookForDealer,
  priceBookFilter,
} from "../../services/dealerServices/priceBookServices";
import { getCategoryAndPriceBooksforDealerPortal } from "../../services/dealerServices/orderListServices";
import Card from "../../common/card";
import { MultiSelect } from "react-multi-select-component";
import InActiveButton from "../../common/inActiveButton";
import SingleView from "../../common/singleView";
function DealerPriceBook(props) {
  console.log(props);
  const [dealerPriceBook, setDealerPriceBook] = useState([]);
  const [selectedAction, setSelectedAction] = useState(null);
  const [priceBookList, setPriceBookList] = useState([]);
  const [isDisapprovedOpen, setIsDisapprovedOpen] = useState(false);
  const [categoryList, setCategoryList] = useState([]);
  const [loading, setLoading] = useState(false);
  const [selected, setSelected] = useState([]);
  const [coverageTypes, setCoverageTypes] = useState([]);
  const [termList, setTermList] = useState([]);
  const [dealerPriceBookDetail, setDealerPriceBookDetail] = useState({});
  const [error, setError] = useState("");
  const dropdownRef = useRef(null);
  const navigate = useNavigate();
  const { priceBookId } = useParams();
  const calculateDropdownPosition = (index) => {
    const isCloseToBottom = priceBookList.length - index <= 10000;
    return isCloseToBottom ? "bottom-[1rem]" : "top-[1rem]";
  };
  
  const paginationOptions = {
    rowsPerPageText: "Rows per page:",
    rangeSeparatorText: "of",
  };

  const routeToEditPage = (value) => {
    localStorage.setItem("menu", "PriceBook");
    console.log(value);
    navigate(`/editDealerBook/${value._id}/${props.id}`);
  };

  const CustomNoDataComponent = () => (
    <Card className="text-center my-5">
      <p>No records found.</p>
    </Card>
  );

  const formatOrderValue = (orderValue) => {
    if (Math.abs(orderValue) >= 1e6) {
      return (orderValue / 1e6).toFixed(2) + "M";
    } else {
      return orderValue.toLocaleString(undefined, {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      });
    }
  };

  const [currentPage, setCurrentPage] = useState(1); // Tracks current page
  const [rowsPerPage, setRowsPerPage] = useState(10); // Tracks rows per page

  // Handle page change
  const handlePageChange = (page) => {
    setCurrentPage(page);
  };

  // Handle rows per page change
  const handleRowsPerPageChange = (newPerPage, page) => {
    setRowsPerPage(newPerPage);
    setCurrentPage(page);
  };

  const columns = [
    {
      name: "Serial #",
      selector: (row, index) => (currentPage - 1) * rowsPerPage + index + 1,
      sortable: true,
      minWidth: "auto",
      maxWidth: "90px",
    },
    {
      name: (
        <div>
          Dealer
          <br />
          SKU
        </div>
      ),
      selector: (row) => row?.dealerSku,
      sortable: true,
    },
    {
      name: (
        <div>
          Product
          <br />
          Name
        </div>
      ),
      selector: (row) => row?.priceBooks?.pName,
      sortable: true,
    },
    {
      name: "Category",
      selector: (row) => row?.priceBooks?.category[0]?.name,
      sortable: true,
    },
    {
      name: (
        <div>
          Price <br /> Type{" "}
        </div>
      ),
      selector: (row) => row?.priceBooks?.priceType,
      sortable: true,
    },
    {
      name: "Term",
      selector: (row) => {
        const months = row.priceBooks?.term;
        if (months) {
          const years = months / 12;
          return `${years} ${years == 1 ? "Year" : "Years"} `;
        }
        return "N/A";
      },
      sortable: true,
    },
    {
      name: (
        <div>
          Retail
          <br />
          Cost
        </div>
      ),
      selector: (row) =>
        `$${row.retailPrice === undefined
          ? parseInt(0).toLocaleString(2)
          : formatOrderValue(row.retailPrice ?? parseInt(0))
        }`,
      sortable: true,
    },

    {
      name: "Action",
      minWidth: "auto",
      maxWidth: "100px",
      cell: (row, index) => {
        return (
          <div className="relative">
            <div
              onClick={() =>
                setSelectedAction(selectedAction === index ? null : index)
              }
            >
              <img
                src={ActiveIcon}
                className="cursor-pointer w-[35px]"
                alt="Active Icon"
              />
            </div>
            {selectedAction === index && (
              <SingleView
                ref={dropdownRef}
                className={`absolute z-[2] w-[80px] justify-center drop-shadow-5xl -right-3 py-1 mt-2 border rounded-lg shadow-md ${calculateDropdownPosition(
                  index
                )}`}
              >
                <div
                  className="text-left py-1 px-2 cursor-pointer w-full flex justify-start"
                  onClick={() => openView(row._id)}
                >
                  <div
                    style={{
                      maskImage: `url(${view})`,
                      WebkitMaskImage: `url(${view})`,
                      maskRepeat: "no-repeat",
                      WebkitMaskRepeat: "no-repeat",
                      maskPosition: "center",
                      WebkitMaskPosition: "center",
                      maskSize: "contain",
                      WebkitMaskSize: "contain",
                    }}
                    className="self-center singleViews mr-2 h-4 w-4 "
                  />
                  {/* <img src={view} className="w-4 h-4 mr-2" /> */}
                  View
                </div>
              </SingleView>
            )}
          </div>
        );
      },
    },
  ];

  const priceBookData = async () => {
    setLoading(true);
    const result =
      props.flag === "reseller"
        ? await getPriceBookListByResellerId(props.id)
        : await getPriceBookForDealer(props.id);
    setPriceBookList(result.result);
    console.log(result.result);
    setLoading(false);
  };

  const getCategoryListData = async () => {
    try {
      const res = await getCategoryAndPriceBooksforDealerPortal();
      let arr = [];
      console.log(res);
      res?.result?.priceCategories.length > 0 &&
        res?.result?.priceCategories?.map((item) => {
          arr.push({ label: item.name, value: item.name });
        });

      setCategoryList(arr);
      console.log(res, "----------------------->>>>>>>>>>>>>");
    } catch (error) {
      console.error("Error fetching category list:", error);
    }
  };
  const getCovrageListData = async () => {
    try {
      const res = await getCovrageList();
      console.log(res);
      setCoverageTypes(
        res.result.value.map((item) => ({
          label: item.label,
          value: item.value,
        }))
      );
    } catch (error) {
      console.error("Error fetching category list:", error);
    }
  };
  const handleSelectChange1 = (name, value) => {
    formik.setFieldValue(name, value.map((item) => item.value))
  };

  const [isViewOpen, setIsViewOpen] = useState(false);

  const closeView = () => {
    setIsViewOpen(false);
  };

  const openView = async (id) => {
    const result = await getPriceBookDetailsForDealerPortal(id);
    setDealerPriceBookDetail(result?.result[0]);
    console.log(result);
    setIsViewOpen(true);
  };

  const getTermListData = async () => {
    try {
      const res = await getTermList();
      console.log(res.result.terms, "==============");
      setTermList(
        res.result.terms.map((item) => ({
          label: item.terms + " Months",
          value: item.terms,
        }))
      );
    } catch (error) {
      console.error("Error fetching category list:", error);
    }
  };

  const pricetype = [
    { label: "Regular Pricing", value: "Regular Pricing" },
    { label: "Flat Pricing", value: "Flat Pricing" },
    { label: "Quantity Pricing", value: "Quantity Pricing" },
  ];
  const formik = useFormik({
    initialValues: {
      dealerSku: "",
      status: "",
      pName: "",
      category: "",
      coverageType: "",
      priceType: "",
      term: "",
      range: "",
    },
    validationSchema: Yup.object({
      dealerSku: Yup.string(),
      pName: Yup.string(),
      status: Yup.boolean(),
      category: Yup.string(),
      priceType: Yup.string(),
      term: Yup.string(),
      range: Yup.string(),
    }),
    onSubmit: (values) => {
      console.log("Form submitted with values:", values);
      filterDealerPriceBook(values);
      closeDisapproved();
    },
  });
  useEffect(() => {
    if(priceBookId!=undefined){
      formik.setFieldValue('dealerSku',priceBookId)
      let data ={...formik.values}
      data.dealerSku=priceBookId
      filterDealerPriceBook(data);

    }
    else{
      priceBookData();
    }
    getTermListData();
  
    getCovrageListData();
  }, []);

  useEffect(() => {
    getCategoryListData();
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        // Close the dropdown if the click is outside of it
        setSelectedAction(null);
      }
    };

    document.addEventListener("click", handleClickOutside);

    return () => {
      document.removeEventListener("click", handleClickOutside);
    };
  }, []);

  const closeDisapproved = () => {
    setIsDisapprovedOpen(false);
  };
  const openDisapproved = () => {
    setIsDisapprovedOpen(true);
  };

  const filterDealerPriceBook = async (values) => {
    if (props.flag === "reseller") {
      values.dealerId = props.dealerId;
    } else {
      values.dealerId = props.id;
    }
    try {
      setLoading(true);
      const res = await priceBookFilter(values);
      if (res.code != 200) {
        setError(res.message);
        setLoading(false);
      } else {
        setLoading(false);
        setError("");
      }
      console.log(res);
      setPriceBookList(res.result);
      setLoading(false);
    } catch (error) {
      setLoading(false);
      console.error("Error fetching category list:", error);
    } finally {
      setLoading(false);
    }
  };



  const handleFilterIconClick = () => {
    formik.resetForm();
    setSelected([])
    console.log(formik.values);
    priceBookData();
  };

  return (
    <>
      <div className="my-8">
        <Headbar />
        <div className="flex mt-2">
          <div className="pl-3">
            <p className="font-bold text-[36px] leading-9	mb-[3px]">
              Price Book
            </p>
            <ul className="flex self-center">
              <li className="text-sm font-semibold ml-1 pt-[1px]">
                {" "}
                Price Book{" "}
              </li>
            </ul>
          </div>
        </div>
        <Card className="mt-6 border-[1px] border-Light-Grey rounded-xl">
          <Grid className="!p-[26px] !pt-[14px] !pb-0">
            <div className="col-span-3 self-center">
              <p className="text-xl font-semibold">Price Book List</p>
            </div>
            <div className="col-span-9">
              <div className="bg-grayf9 rounded-[30px] p-3 border-[1px] border-Light-Grey">
                <form onSubmit={formik.handleSubmit}>
                  <Grid className="!grid-cols-9">
                    <div className="col-span-2 self-center">
                      <Input
                        name="dealerSku"
                        type="text"
                        placeholder="Dealer SKU"
                        className="!text-[14px] !bg-White-Smoke"
                        className1="!text-[13px] !pt-1 placeholder-opacity-50 !pb-1 placeholder-Black-Russian !bg-[white]"
                        label=""
                        value={formik.values.dealerSku}
                        onChange={formik.handleChange}
                        onBlur={formik.handleBlur}
                      />
                    </div>
                    <div className="col-span-2 self-center">
                      <Select
                        name="term"
                        label=""
                        options={termList}
                        OptionName="Term"
                        color="text-Black-Russian opacity-50"
                        className1="!pt-1 !pb-1 !text-[13px] !bg-[white]"
                        className="!text-[14px]  !bg-White-Smoke"
                        value={formik.values.term}
                        onChange={formik.setFieldValue}
                      />
                    </div>

                    <div className="col-span-2 self-center">
                      <Select
                        name="priceType"
                        label=""
                        options={pricetype}
                        OptionName="Price Type"
                        color="text-Black-Russian opacity-50"
                        className1="!pt-1 !pb-1 !text-[13px] !bg-[white]"
                        className="!text-[14px]  !bg-White-Smoke"
                        value={formik.values.priceType}
                        onChange={formik.setFieldValue}
                      />
                    </div>
                    <div className="col-span-3 self-center flex justify-center">
                      <Button type="submit" className="!p-2">
                        <img
                          src={Search}
                          className="cursor-pointer	mx-auto "
                          alt="Search"
                        />
                      </Button>
                      <InActiveButton
                        type="button"
                        className=" mr-3"
                        onClick={handleFilterIconClick}
                      >
                        <div
                          style={{
                            maskImage: `url(${clearFilter})`,
                            WebkitMaskImage: `url(${clearFilter})`,
                            maskRepeat: "no-repeat",
                            WebkitMaskRepeat: "no-repeat",
                            maskPosition: "center",
                            WebkitMaskPosition: "center",
                            maskSize: "contain",
                            WebkitMaskSize: "contain",
                          }}
                          className="self-center pr-1 py-1 h-4 w-4 cursor-pointer mx-auto"
                        />
                      </InActiveButton>
                      <Button
                        className="!text-[13px]"
                        onClick={() => openDisapproved()}
                      >
                        Advance Search
                      </Button>
                    </div>
                  </Grid>
                </form>
              </div>
            </div>
          </Grid>
          <div className="mb-5 relative">
            {loading ? (
              <div className=" h-[400px] w-full flex py-5">
                <div className="self-center mx-auto">
                  <RotateLoader color="#333" />
                </div>
              </div>
            ) : (
              <DataTable
                draggableColumns={false}
                columns={columns}
                data={priceBookList}
                highlightOnHover
                sortIcon={
                  <>
                    {" "}
                    <div
                      style={{
                        maskImage: `url(${shorting})`,
                        WebkitMaskImage: `url(${shorting})`,
                        maskRepeat: "no-repeat",
                        WebkitMaskRepeat: "no-repeat",
                        maskPosition: "center",
                        WebkitMaskPosition: "center",
                        maskSize: "contain",
                        WebkitMaskSize: "contain",
                      }}
                      className="ml-2 tabless"
                    />
                    {/* <img src={shorting} className="ml-2" alt="shorting" /> */}
                  </>
                }
                noDataComponent={<CustomNoDataComponent />}
                pagination
                paginationPerPage={10}
                paginationComponentOptions={paginationOptions}
                onChangePage={handlePageChange}
                onChangeRowsPerPage={handleRowsPerPageChange}
                paginationRowsPerPageOptions={[10, 20, 50, 100]}
              />
            )}
          </div>
        </Card>
      </div>

      <Modal className="!w-[900px]" isOpen={isViewOpen} onClose={closeView}>
        <Button
          onClick={closeView}
          className="absolute right-[-13px] top-0 h-[80px] w-[80px] !p-[19px] mt-[-9px] !rounded-full !bg-Granite-Gray"
        >
          <img
            src={Cross}
            className="w-full h-full text-black rounded-full p-0"
          />
        </Button>
        <div className="py-3">
          <p className="text-center text-3xl font-semibold  w-[70%] mx-auto">
            View Price Book Details
          </p>
          <Grid className="mt-5 px-6">
            <div className="col-span-4">
              <p className="text-lg font-bold">Product Name</p>
              <p className="text-base font-semibold">
                {dealerPriceBookDetail?.priceBooks?.pName}
              </p>
            </div>
            <div className="col-span-4">
              <p className="text-lg font-bold">Dealer SKU</p>
              <p className="text-base font-semibold">
                {dealerPriceBookDetail?.dealerSku}
              </p>
            </div>
            <div className="col-span-4">
              <p className="text-lg font-bold">Price Type</p>
              <p className="text-base font-semibold">
                {dealerPriceBookDetail?.priceBooks?.priceType}
              </p>
            </div>
            <div className="col-span-4">
              <p className="text-lg font-bold">Product Category</p>
              <p className="text-base font-semibold">
                {dealerPriceBookDetail?.priceBooks?.category[0].name}{" "}
              </p>
            </div>
            <div className="col-span-4">
              <p className="text-lg  font-semibold">
                Retail Price
              </p>
              <p className="text-base font-semibold">
                $
                {dealerPriceBookDetail?.retailPrice === undefined
                  ? parseInt(0).toLocaleString(2)
                  : formatOrderValue(
                    dealerPriceBookDetail?.retailPrice ?? parseInt(0)
                  )}
              </p>
            </div>
            <div className="col-span-4">
              <p className="text-lg font-bold">Term</p>
              <p className="text-base font-semibold">
                {dealerPriceBookDetail?.priceBooks?.term} Months
              </p>
            </div>

            <div className="col-span-12">
              <p className="text-lg font-bold">Description</p>
              <p className="text-base font-semibold">
                {dealerPriceBookDetail?.priceBooks?.category[0].description}
              </p>
            </div>

          </Grid>
          <Grid className="px-6 mt-5">
            <div className="col-span-3">
              <p className="text-base mb-3 font-semibold">
                # of Claims Over the Certain Period
              </p>
              <p className="text-[14px] font-semibold">
                {/* {dealerPriceBookDetail?.noOfClaim?.period} -{" "} */}
                {
                  dealerPriceBookDetail?.noOfClaim?.value == "-1"
                    ? ""
                    : `${dealerPriceBookDetail?.noOfClaim?.period} - `
                }
                {dealerPriceBookDetail?.noOfClaim?.value == -1
                  ? "Unlimited"
                  : dealerPriceBookDetail?.noOfClaim?.value}
              </p>
            </div>
            <div className="col-span-3">
              <p className="text-base mb-3 font-semibold">
                # of Claims in Coverage <br /> Period
              </p>
              <p className="text-[14px] font-semibold">
                {dealerPriceBookDetail?.noOfClaimPerPeriod == -1
                  ? "Unlimited"
                  : dealerPriceBookDetail?.noOfClaimPerPeriod}
              </p>
            </div>
            <div className="col-span-3">
              <p className=" text-base mb-3 font-semibold">
                {" "}
                Is manufacturer warranty included?
              </p>
              <p className="text-[14px] font-semibold">
                {dealerPriceBookDetail?.isManufacturerWarranty == true
                  ? "Yes"
                  : "No"}
              </p>
            </div>
            <div className="col-span-3">
              <p className=" text-base mb-3 font-semibold">
                {" "}
                Is There a Maximum Claim Amount?
              </p>
              <p className="text-[14px] font-semibold">
                {dealerPriceBookDetail?.isMaxClaimAmount == true
                  ? "Yes"
                  : "No"}
              </p>
            </div>
            <div className="col-span-12">
              <table className="w-full border text-center">
                <tr className="border staticTable">
                  <th>Coverage Type</th>
                  <th>Waiting Days</th>
                  <th>Deductible Amount</th>
                </tr>

                {dealerPriceBookDetail?.adhDays1 &&
                  dealerPriceBookDetail?.adhDays1.length > 0 && (
                    <>
                      {dealerPriceBookDetail?.adhDays1.map((type, index) => (
                        <tr key={index} className="border">
                          <td className="font-semibold mx-5">{type.label}</td>
                          <td className="font-semibold mx-5">
                            {type.waitingDays}
                          </td>
                          <td className="font-semibold mx-5">
                            {type.amountType === "percentage"
                              ? `${formatOrderValue(
                                Number(type.deductible) ?? 0
                              )} %`
                              : `$${formatOrderValue(
                                Number(type.deductible) ?? 0
                              )}`}
                          </td>
                        </tr>
                      ))}
                    </>
                  )}
              </table>
            </div>

            {dealerPriceBookDetail?.priceBooks?.priceType == "Flat Pricing" && (
              <>
                <div className="col-span-4">
                  <p className="text-lg font-bold">Start Range</p>
                  <p className="text-base font-semibold">
                    {" "}
                    $
                    {dealerPriceBookDetail?.priceBooks?.rangeStart === undefined
                      ? parseInt(0).toLocaleString(2)
                      : formatOrderValue(
                        dealerPriceBookDetail?.priceBooks?.rangeStart ??
                        parseInt(0)
                      )}
                  </p>
                </div>
                <div className="col-span-4">
                  <p className="text-lg font-bold">End Range</p>
                  <p className="text-base font-semibold">
                    $
                    {dealerPriceBookDetail?.priceBooks?.rangeEnd === undefined
                      ? parseInt(0).toLocaleString(2)
                      : formatOrderValue(
                        dealerPriceBookDetail?.priceBooks?.rangeEnd ??
                        parseInt(0)
                      )}
                  </p>
                </div>
              </>
            )}
            {dealerPriceBookDetail?.priceBooks?.priceType ==
              "Quantity Pricing" && (
                <>
                  <div className="col-span-12">
                    <table className="w-full border text-center">
                      <tr className="border staticTable">
                        <th colSpan={"2"}>Quantity Pricing List </th>
                      </tr>
                      <tr className="border staticTable">
                        <th className="w-[50%]">Name</th>
                        <th className="w-[50%]">Max Quantity</th>
                      </tr>
                      {dealerPriceBookDetail?.priceBooks?.quantityPriceDetail
                        .length !== 0 &&
                        dealerPriceBookDetail?.priceBooks?.quantityPriceDetail.map(
                          (item, index) => (
                            <tr key={index} className="border">
                              <td>{item.name}</td>
                              <td>{item.quantity}</td>
                            </tr>
                          )
                        )}
                    </table>
                  </div>
                </>
              )}
          </Grid>
        </div>
      </Modal>

      <Modal isOpen={isDisapprovedOpen} onClose={closeDisapproved}>
        <Button
          onClick={closeDisapproved}
          className="absolute right-[-13px] top-0 h-[80px] w-[80px] !p-[19px] mt-[-9px] !rounded-full !bg-Granite-Gray"
        >
          <img
            src={Cross}
            className="w-full h-full text-black rounded-full p-0"
          />
        </Button>
        <form onSubmit={formik.handleSubmit}>
          <div className="py-3">
            <p className="text-center text-3xl font-semibold ">
              Advance Search
            </p>
            <Grid className="mt-5 px-6">
              <div className="col-span-6">
                <Input
                  type="text"
                  name="dealerSku"
                  className="!bg-white"
                  label="Dealer SKU"
                  placeholder=""
                  value={formik.values.dealerSku}
                  onChange={formik.handleChange}
                  onBlur={formik.handleBlur}
                />
              </div>

              <div className="col-span-6">
                <Input
                  type="text"
                  name="pName"
                  className="!bg-white"
                  label="Product Name"
                  placeholder=""
                  value={formik.values.pName}
                  onChange={formik.handleChange}
                  onBlur={formik.handleBlur}
                />
              </div>
              <div className="col-span-6">
                <div className="relative">
                  <label
                    htmlFor="coverageType"
                    className="absolute text-base font-Regular text-[#5D6E66] leading-6 duration-300 transform origin-[0] top-1 bg-white left-2 px-1 -translate-y-4 scale-75"
                  >
                    Coverage Type
                  </label>
                  <div className="block w-full text-base font-semibold bg-transparent rounded-lg border border-gray-300">
                    <MultiSelect
                      label="Coverage Type"
                      name="coverageType"
                      placeholder=""
                      className={`SearchSelect css-b62m3t-container red !border-[0px] p-[0.425rem] `}
                      styles={{
                        chips: (provided) => ({
                          ...provided,
                          backgroundColor:
                            "#f0ad4e",
                          color: "white",
                        }),
                        searchBox: (provided) => ({
                          ...provided,
                          backgroundColor:
                            "#f7f7f7",
                          border:
                            "1px solid #ddd",
                          cursor: "pointer",
                        }),
                        option: (provided, state) => ({
                          ...provided,
                          backgroundColor: state.isSelected
                            ? "#f0ad4e"
                            : "white",
                          color: state.isSelected ? "white" : "black",
                          "&:hover": {
                            backgroundColor:
                              "#f0ad4e",
                            color: "white",
                          },
                        }),
                      }}
                      onChange={(value) => {
                        setSelected(value);
                        handleSelectChange1("coverageType", value);
                      }}
                      options={coverageTypes}
                      value={selected}
                      onBlur={formik.handleBlur}
                      error={
                        formik.touched.coverageType &&
                        formik.errors.coverageType
                      }
                    />
                  </div>
                  {formik.touched.coverageType &&
                    formik.errors.coverageType && (
                      <div className="text-red-500 text-sm pl-2 pt-2">
                        {formik.errors.coverageType}
                      </div>
                    )}
                </div>
              </div>
              <div className="col-span-6">
                <Input
                  type="text"
                  name="category"
                  className="!bg-white"
                  label="Category"
                  placeholder=""
                  value={formik.values.category}
                  onChange={formik.handleChange}
                  onBlur={formik.handleBlur}
                />
                {/* <Select
                        name="category"
                        label="Category"
                        options={categoryList}
                        OptionName="Category"
                        color="text-Black-Russian opacity-50"
                        className="!text-[14px] !bg-white"
                        value={formik.values.category}
                        onChange={formik.setFieldValue}
                      /> */}
              </div>
              <div className="col-span-6">
                <Select
                  name="priceType"
                  label="Price Type"
                  options={pricetype}
                  OptionName="Price Type"
                  color="text-Black-Russian opacity-50"
                  className="!text-[14px] !bg-white"
                  value={formik.values.priceType}
                  onChange={formik.setFieldValue}
                />
              </div>

              <div className="col-span-6">
                <Select
                  name="term"
                  label="Term"
                  options={termList}
                  OptionName="Term"
                  color="text-Black-Russian opacity-50"
                  className="!text-[14px] !bg-white"
                  value={formik.values.term}
                  onChange={formik.setFieldValue}
                />
              </div>
              {formik.values.priceType == "Flat Pricing" && (
                <div className="col-span-6">
                  <Input
                    type="text"
                    name="range"
                    className="!bg-white"
                    label="Product Price Range"
                    placeholder=""
                    value={formik.values.range}
                    onChange={formik.handleChange}
                    onBlur={formik.handleBlur}
                  />
                </div>
              )}

              {/* <div className="col-span-6">
                  <Select
                        name="status"
                        label="Status"
                        options={status}
                        OptionName="Status"
                        color="text-Black-Russian opacity-50"
                        // className1="!pt-1 !pb-1 !text-[13px] !bg-[white]"
                        className="!text-[14px] !bg-white"
                        value={formik.values.status}
                        onChange={formik.setFieldValue}
                    />
                  </div> */}
              <div className="col-span-12">
                <Button type="submit" className={"w-full"}>
                  Search
                </Button>
              </div>
            </Grid>
          </div>
        </form>
      </Modal>
    </>
  );
}

export default DealerPriceBook;
