import React, { useEffect, useState } from "react";
import Headbar from "../../../common/headBar";
import { Link, useNavigate, useParams } from "react-router-dom";
import Grid from "../../../common/grid";
import Button from "../../../common/button";

// Media Import
import BackImage from "../../../assets/images/icons/backArrow.svg";
import Bank from "../../../assets/images/icons/bankIcon.svg";
import address from "../../../assets/images/Dealer/Address.svg";
import name from "../../../assets/images/Dealer/Name.svg";
import AddItem from "../../../assets/images/icons/addItem.svg";
import DealerActive from "../../../assets/images/icons/dealerDetails.svg";
import ClaimActive from "../../../assets/images/Dealer/Claim-active.svg";
import UserActive from "../../../assets/images/Dealer/User-active.svg";
import Dealer from "../../../assets/images/icons/dealer.svg";
import view from "../../../assets/images/eye.png";
import Unpaid from "../../../assets/images/icons/Unpaid.svg";
import UnpaidActive from "../../../assets/images/icons/unpaidActive.svg";
import Paid from "../../../assets/images/icons/Paid.svg";
import ActivePaid from "../../../assets/images/icons/ActivePaid.svg";
import Claim from "../../../assets/images/Dealer/Claim.svg";
import User from "../../../assets/images/Dealer/Users.svg";
import email from "../../../assets/images/Dealer/Email.svg";
import phone from "../../../assets/images/Dealer/Phone.svg";
import ClaimList from "../../dashboard/Claim/claimList";
import ClaimList12 from "../../dashboard/Dealer/Dealer-Details/claim";
import UserList from "../Dealer/Dealer-Details/user";
import Modal from "../../../common/model";
import Input from "../../../common/input";
import Select from "../../../common/select";
import DealerDetailList from "../Dealer/Dealer-Details/dealer";
import {
  checkUserToken,
  getUserListByDealerId,
} from "../../../services/userServices";
import RadioButton from "../../../common/radio";
import { useFormik } from "formik";
import DataTable from "react-data-table-component";
import { MyContextProvider, useMyContext } from "../../../context/context";
import * as Yup from "yup";
import {
  addUserByServicerId,
  changeServicerStatus,
  createRelationWithServicer,
  getDealerListByServicerId,
  getServicerDetailsByServicerId,
  getServicerUsersById,
} from "../../../services/servicerServices";
import { RotateLoader } from "react-spinners";
import Primary from "../../.././assets/images/SetPrimary.png";
import { cityData } from "../../../stateCityJson";
import shorting from "../../../assets/images/icons/shorting.svg";
import { getUserDetailsFromLocalStorage } from "../../../services/extraServices";
import SingleView from "../../../common/singleView";
import InActiveButton from "../../../common/inActiveButton";
import ServicerSetting from "../Dealer/Dealer-Details/servicerSetting";
import Card from "../../../common/card";

function ServicerDetails() {
  const getInitialActiveTab = () => {
    const storedTab = localStorage.getItem("servicer");
    return storedTab ? storedTab : "Claims";
  };
  const [activeTab, setActiveTab] = useState(getInitialActiveTab()); // Set the initial active tab
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState("");
  const [isModalOpen1, setIsModalOpen1] = useState(false);
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [userLoader, setUserLoader] = useState(false);
  const [refreshList, setRefreshUserList] = useState([]);
  const [modalOpen, setModalOpen] = useState(false);
  const { servicerId } = useParams();
  const [loading, setLoading] = useState(false);
  const [firstMessage, setFirstMessage] = useState("");
  const [secondMessage, setSecondMessage] = useState("");
  const [servicerDetails, setServicerDetails] = useState({});
  const [createAccountOption, setCreateAccountOption] = useState("yes");
  const [createAccount, setCreateAccount] = useState(true);
  const [timer, setTimer] = useState(3);
  const { flag, toggleFlag } = useMyContext();
  const [dealerList, setDealerList] = useState([]);
  const [flagValue, setFlagValue] = useState(false);
  const [initialUserFormValues, setInitialUserFormValues] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNumber: "",
    position: "",
    status: "yes",
    servicerId: servicerId,
    isPrimary: false,
  });
  const [initialFormValues, setInitialFormValues] = useState({
    name: "",
    dealerId: "",
    street: "",
    city: "",
    zip: "",
    state: "",
    country: "USA",
    oldName: "",
    isAccountCreate: createAccount,
  });
  const state = cityData;
  // const { flag } = useMyContext();
  const emailValidationRegex = /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,4}$/i;
  const modalOpen1 = () => {
    getDealerList();
    setIsModalOpen1(true);
  };
  const routeToPage = (data) => {
    // console.log(data, id.id);
    switch (data) {
      case "Users":
        openUserModal();
        localStorage.setItem("servicer", "Users");
        break;
      case "Dealer":
        modalOpen1();
        localStorage.setItem("servicer", "Dealer");
        break;
      default:
        console.log("Invalid data, no navigation");
    }
  };
  const closeModal = () => {
    setIsModalOpen(false);
    formik.resetForm();
  };
  useEffect(() => {
    localStorage.setItem("servicer", activeTab);
    checkTokenExpiry();
  }, [activeTab]);

  const checkTokenExpiry = async () => {
    try {
      const response = await checkUserToken();
      console.log(response.code == 200);
      if (response.code == 200) {
        return;
      } else {
        navigate(`/`);
        localStorage.removeItem("userDetails");
      }
    } catch (error) {
      navigate(`/`);
      localStorage.removeItem("userDetails");
    } finally {
    }
  };
  useEffect(() => {
    getUserList();
  }, []);
  useEffect(() => {
    setLoading(true);
    let intervalId;

    if (modalOpen && timer > 0) {
      intervalId = setInterval(() => {
        setTimer((prevTimer) => prevTimer - 1);
      }, 1000);
    }

    if (timer === 0) {
      closeModal10();
    }

    if (!modalOpen) {
      clearInterval(intervalId);
      setTimer(3);
    }

    setLoading(false);

    return () => {
      clearInterval(intervalId);
    };
  }, [modalOpen, timer]);

  const openUserModal = () => {
    setActiveTab("Users123");
    localStorage.setItem("isPopupOpen", "true");
    setIsUserModalOpen(true);
  };
  const closeModal10 = () => {
    setModalOpen(false);
  };
  const openModal = () => {
    setIsModalOpen(true);
  };
  const closeModal1 = () => {
    setIsModalOpen1(false);
  };
  const closeUserModal = () => {
    setIsUserModalOpen(false);
    setActiveTab("Users");
    localStorage.setItem("isPopupOpen", "false");
    userValues.resetForm();
  };
  const getUserList = async () => {
    const result = await getServicerUsersById(servicerId, {});
    console.log(result.result, "----------");
    setRefreshUserList(result.result);
  };
  useEffect(() => {
    const isPopupOpen = localStorage.getItem("isPopupOpen") === "true";
    if (isPopupOpen) {
      setActiveTab("Users");
    }
  }, []);

  const handleSelectChange1 = (label, value) => {
    setSelectedProduct(value);
  };
  const handleRadioChange = (event) => {
    const selectedValue = event.target.value;
    userValues.setFieldValue("status", selectedValue === "yes" ? true : false);
    setCreateAccountOption(selectedValue);
  };

  const CustomNoDataComponent = () => (
    <Card className="text-center">
      <p>No records found.</p>
    </Card>
  );
  const columns = [
    {
      name: "Serial #  ",
      selector: (row, index) => index + 1,
      sortable: true,
      minWidth: "33%",
      center: true,
    },
    {
      name: "Dealer Name",
      selector: (row) => row.name,
      sortable: true,
      minWidth: "50%",
      center: true,
    },
    {
      name: "Action",
      center: true,
      minWidth: "12%",
      cell: (row, index) => {
        return (
          <div>
            <input
              type="checkbox"
              className="accent-gray-600"
              checked={row.check}
              onChange={(e) => {
                const checked = e.target.checked;
                const itemId = dealerList[index]._id;
                dealerList[index].check = checked;
                const selectedItems = checked
                  ? [...dealerForm.values.selectedItems, itemId]
                  : dealerForm.values.selectedItems.filter(
                    (id) => id !== itemId
                  );

                dealerForm.setFieldValue("selectedItems", selectedItems);
              }}
            />
          </div>
        );
      },
    },
  ];
  const tabs = [
    {
      id: "Claims",
      label: "Claims",
      icons: Claim,
      Activeicons: ClaimActive,
      content: activeTab === "Claims" && (
        <ClaimList id={servicerId} flag="servicer" activeTab={activeTab} />
      ),
    },
    {
      id: "Dealer",
      label: "Dealer",
      icons: Dealer,
      Activeicons: DealerActive,
      content: activeTab === "Dealer" && (
        <DealerDetailList
          id={servicerId}
          flag={flagValue}
          activeTab={activeTab}
        />
      ),
    },
    {
      id: "Users",
      label: "Users",
      icons: User,
      Activeicons: UserActive,
      content: (
        <UserList flag={"servicer"} id={servicerId} activeTab={activeTab} setLoading={setLoading} />
      ),
    },
    {
      id: "Settings",
      label: "Settings",
      icons: Paid,
      Activeicons: ActivePaid,
      content: activeTab === "Settings" && (
        <ServicerSetting id={servicerId} flag="servicer" activeTab={activeTab} />
      ),
    },
    {
      id: "Unpaid Claims",
      label: "Unpaid Claims",
      icons: Unpaid,
      Activeicons: UnpaidActive,
      content: activeTab === "Unpaid Claims" && (
        <ClaimList12 id={servicerId} flag="servicer" activeTab={activeTab} />
      ),
    },
    {
      id: "Paid Claims",
      label: "Paid Claims",
      icons: Paid,
      Activeicons: ActivePaid,
      content: activeTab === "Paid Claims" && (
        <ClaimList12 id={servicerId} flag="servicer" activeTab={activeTab} />
      ),
    },

  ];

  const handleSelectChange = async (name, value) => {
    formik.setFieldValue(name, value);
  };
  const getDealerList = async () => {
    // setLoading(true);
    const result = await getDealerListByServicerId(servicerId);
    setDealerList(result.result);
    console.log(result.result);
    // setLoading(false);
  };
  useEffect(() => {
    servicerDetail();
    getDealerList();
  }, [servicerId, flag]);

  const dealerForm = useFormik({
    initialValues: {
      selectedItems: [],
    },

    onSubmit: async (values) => {
      setFlagValue(false);
      setLoading(true);
      const selectedData = dealerList.map((item) => ({
        _id: item._id,
        status: values.selectedItems.includes(item._id) || item.check,
      }));

      console.log("Selected Data: ", selectedData);

      const result = await createRelationWithServicer(servicerId, {
        dealers: selectedData,
      });
      console.log(result);
      if (result.code === 200) {
        setLoading(false);
        setFlagValue(true);
        setModalOpen(true);
        setFirstMessage("Dealer Assigned Successfully");
        setSecondMessage("Dealer Assigned Successfully");
        getDealerList();
        setTimer(3);
        closeModal1();
      } else {
        setLoading(false);
        getDealerList();
        closeModal1();
      }

      closeModal1();
      dealerForm.resetForm();
    },
  });

  const formatPhoneNumber = (phoneNumber) => {
    const cleaned = ("" + phoneNumber).replace(/\D/g, ""); // Remove non-numeric characters
    const match = cleaned.match(/^(\d{3})(\d{3})(\d{4})$/); // Match groups of 3 digits

    if (match) {
      return `(${match[1]}) ${match[2]}-${match[3]}`;
    }

    return phoneNumber; // Return original phone number if it couldn't be formatted
  };

  const handleAccountChange = (event) => {
    const valueAsBoolean = JSON.parse(event.target.value.toLowerCase());
    setCreateAccount(valueAsBoolean);
    formik.setFieldValue("isAccountCreate", valueAsBoolean);
  };

  const servicerDetail = async () => {
    setLoading(true);
    const res = await getServicerDetailsByServicerId(servicerId);
    if (res.code == 200) {
      setServicerDetails(res.message);
      console.log(res.message);
      setCreateAccount(res?.message?.meta?.isAccountCreate);
      setCreateAccountOption(
        res?.message?.meta?.isAccountCreate === false ? "no" : "yes"
      );
      setInitialFormValues({
        name: res?.message?.meta?.name,
        oldName: res?.message?.meta?.name,
        servicerId: servicerId,
        street: res?.message?.meta?.street,
        city: res?.message?.meta?.city,
        zip: res?.message?.meta?.zip,
        state: res?.message?.meta?.state,
        country: "USA",
        isAccountCreate: res?.message?.meta?.isAccountCreate,
      });
    }
    else {
      navigate(`/`);
    }
    setLoading(false);
  };
  const userValues = useFormik({
    initialValues: initialUserFormValues,
    enableReinitialize: true,
    validationSchema: Yup.object({
      firstName: Yup.string()
        .transform((originalValue) => originalValue.trim())
        .required("Required")
        .max(500, "Must be exactly 500 characters"),
      lastName: Yup.string()
        .transform((originalValue) => originalValue.trim())
        .required("Required")
        .max(500, "Must be exactly 500 characters"),
      phoneNumber: Yup.string()
        .required("Required")
        .min(10, "Must be at least 10 characters")
        .max(10, "Must be exactly 10 characters")
        .matches(/^[0-9]+$/, "Must contain only digits"),
      email: Yup.string()
        .transform((originalValue) => originalValue.trim())
        .matches(emailValidationRegex, "Invalid email address")
        .required("Required"),
    }),

    onSubmit: async (values, { setFieldError }) => {
      localStorage.setItem("servicer", "Users");
      setUserLoader(true);
      console.log(values);
      setLoading(true);
      if (values.status === "yes") {
        values.status = true;
      }
      const result = await addUserByServicerId(values, servicerId);
      console.log(result.code);
      if (result.code == 200) {
        getUserList();
        setLoading(false);
        closeUserModal();
        setTimer(3);
        setModalOpen(true);
        setFirstMessage("New Users Added Successfully");
        setSecondMessage("New User Added Successfully");
      } else {
        console.log(result);
        if (result.code === 401) {
          setFieldError("email", "Email already in use");
        }
        setLoading(false);
      }
      setUserLoader(false);
    },
  });
  const formatOrderValue = (orderValue) => {
    if (Math.abs(orderValue) >= 1e6) {
      return (orderValue / 1e6).toFixed(2) + "M";
    } else {
      return orderValue.toLocaleString(undefined, {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      });
    }
  };

  const handleTabClick = (tabId) => {
    setActiveTab(tabId);
  };
  const formik = useFormik({
    initialValues: initialFormValues,
    enableReinitialize: true,
    validationSchema: Yup.object({
      // dealerId: Yup.string().required("Required"),
      name: Yup.string()
        .transform((originalValue) => originalValue.trim())
        .required("Required")
        .max(500, "Must be exactly 500 characters"),
      street: Yup.string()
        .transform((originalValue) => originalValue.trim())
        .required("Required")
        .max(500, "Must be exactly 500 characters"),
      state: Yup.string()
        .transform((originalValue) => originalValue.trim())
        .required("Required"),
      city: Yup.string()
        .transform((originalValue) => originalValue.trim())
        .required("Required"),
      country: Yup.string().required("Required"),
      zip: Yup.string()
        .required("Required")
        .min(5, "Must be at least 5 characters")
        .max(6, "Must be exactly 6 characters"),
    }),

    onSubmit: async (values) => {
      console.log(values);
      setLoading(true);
      const result = await changeServicerStatus(servicerId, values);

      console.log(result);
      if (result.code == 200) {
        setLoading(false);
        setModalOpen(true);
        servicerDetail();
        setIsModalOpen(false);
        setTimer(3);
        setFirstMessage("Updated Successfully");
        setSecondMessage("Servicer Updated Successfully");

        // setMessage("Dealer updated Successfully");
      } else if (result.message == "Servicer already exist with this name") {
        setLoading(false);
        formik.setFieldError("name", "Name Already Used");
      } else {
        setLoading(false);
        setTimer(3);
      }
    },
  });
  const navigate = useNavigate();
  const handleGOBack = () => {
    localStorage.removeItem("servicer");
    navigate("/servicerList");
  };
  const [buttonTextColor, setButtonTextColor] = useState('');
  const [backGroundColor, setBackGroundColor] = useState('');

  useEffect(() => {
    const storedUserDetails = getUserDetailsFromLocalStorage();

    if (storedUserDetails) {
      const colorScheme = storedUserDetails.colorScheme;
      colorScheme?.forEach(color => {
        switch (color.colorType) {
          case 'inActiveButtonColor':
            setBackGroundColor(color.colorCode);
            break;
          case 'buttonTextColor':
            setButtonTextColor(color.colorCode);
            break;
          default:
            break;
        }
      });
    }
  }, []);


  const InactiveTabButton = ({ tab, onClick }) => (
    <InActiveButton
      className="flex self-center mr-2 w-[98%] !px-2 !py-1 rounded-xl border-[1px] border-Light-Grey "
      onClick={onClick}
    >
      <div
        style={{
          maskImage: `url(${tab.icons})`,
          WebkitMaskImage: `url(${tab.icons})`,
          maskRepeat: "no-repeat",
          WebkitMaskRepeat: "no-repeat",
          maskPosition: "center",
          WebkitMaskPosition: "center",
          maskSize: "contain",
          WebkitMaskSize: "contain",
        }}
        className="self-center pr-1 py-1 h-4 w-4"
      />
      <span
        style={{
          borderLeftWidth: "1px",
          paddingLeft: "7px",
        }}
        className="ml-1 py-1 text-[13px] font-Regular"
      >
        {tab.label}
      </span>
    </InActiveButton>
  );

  // ActiveTabButton Component
  const ActiveTabButton = ({ tab, onClick }) => (
    <Button
      className="flex self-center mr-2 w-[98%] !px-2 !py-1 rounded-xl border-[1px] border-Light-Grey"
      onClick={onClick}
    >
      <div
        style={{
          maskImage: `url(${tab.Activeicons})`,
          WebkitMaskImage: `url(${tab.Activeicons})`,
          backgroundColor: buttonTextColor,
          maskRepeat: "no-repeat",
          WebkitMaskRepeat: "no-repeat",
          maskPosition: "center",
          WebkitMaskPosition: "center",
          maskSize: "contain",
          WebkitMaskSize: "contain",
        }}
        className="self-center pr-1 py-1 h-4 w-4"
      />
      <span
        style={{
          borderColor: buttonTextColor,
          borderLeftWidth: "1px",
          paddingLeft: "7px",
          color: buttonTextColor,
        }}
        className="ml-1 py-1 text-[13px] font-Regular"
      >
        {tab.label}
      </span>
    </Button>
  );

  return (
    <>
      {loading && (
        <div className=" fixed z-[999999] bg-[#333333c7] backdrop-blur-xl  h-screen w-full flex py-5">
          <div className="self-center mx-auto">
            <RotateLoader color="#fff" />
          </div>
        </div>
      )}
      <div className="py-8 pl-3 relative ">
        <Headbar />

        <div className="flex">
          <Link
            to={"/servicerList"}
            className="h-[60px] w-[60px] flex border-[1px] bg-white border-Light-Grey rounded-[25px]"
          >
            <img
              src={BackImage}
              className="m-auto my-auto self-center bg-white"
              alt="BackImage"
            />
          </Link>
          <div className="pl-3">
            <p className="font-bold text-[36px] leading-9 mb-[3px]">
              Servicer Details
            </p>
            <ul className="flex self-center">
              <li className="text-sm  font-Regular">
                <Link to={"/"}>Home / </Link>{" "}
              </li>
              <li className="text-sm  ml-1 font-Regular">
                <Link to={"/servicerList"}> Servicer List / </Link>{" "}
              </li>
              <li className="text-sm  font-semibold ml-1 pt-[1px]">
                {" "}
                Servicer Details ({activeTab})
              </li>
            </ul>
          </div>
        </div>

        <Grid className="!grid-cols-4 mt-5">
          <div className="col-span-1 max-h-[85vh] overflow-y-scroll">
            <SingleView className="   p-5 rounded-[20px]">
              <Grid>
                <div className="col-span-9">
                  <p className="text-sm font-Regular">
                    Account Name
                  </p>
                  <p className="text-xl font-semibold break-words">
                    {servicerDetails?.meta?.name}
                  </p>
                </div>
                <div className="col-span-3 text-end">
                  <Button
                    className="border !border-Bright-Grey !text-sm !font-Regular"
                    onClick={openModal}
                  >
                    Edit
                  </Button>
                </div>
              </Grid>
              <div className="flex my-4">
                <img
                  src={address}
                  className="mr-3 bg-Onyx rounded-[14px] my-auto"
                  alt="Address"
                />
                <div>
                  <p className="text-sm font-Regular mt-3">
                    Address
                  </p>
                  <p className="text-base font-semibold leading-5">
                    {servicerDetails?.meta?.street},{" "}
                    {servicerDetails?.meta?.city},{" "}
                    {servicerDetails?.meta?.state}, {servicerDetails?.meta?.zip}
                    , USA
                  </p>
                </div>
              </div>
              {/* <div className="flex my-4">
              <img
                src={Bank}
                className="mr-3 bg-Onyx rounded-[14px] self-start mt-3"
                alt="Bank"
              />
              <div>
                <p className="text-sm text-neutral-grey font-Regular mt-3">
                  Bank Details
                </p>
                <div className="bg-Onyx border border-[#D1D9E24D] rounded-lg px-2.5 py-2 mt-1">
                  <Grid className="!gap-1">
                    <div className="col-span-6">
                      <p className="text-[10px] text-neutral-grey font-Regular">
                        Bank Name:
                      </p>
                      <p className="text-sm text-white font-semibold leading-5">
                        XYZ Bank
                      </p>
                    </div>
                    <div className="col-span-6">
                      <p className="text-[10px] text-neutral-grey font-Regular">
                        Account Number:
                      </p>
                      <p className="text-sm text-white font-semibold leading-5">
                        987654321
                      </p>
                    </div>
                    <div className="col-span-6">
                      <p className="text-[10px] text-neutral-grey font-Regular">
                        ABA Routing Number:
                      </p>
                      <p className="text-sm text-white font-semibold leading-5">
                        123456789
                      </p>
                    </div>
                    <div className="col-span-6">
                      <p className="text-[10px] text-neutral-grey font-Regular">
                        Account Holder:
                      </p>
                      <p className="text-sm text-white font-semibold leading-5">
                        John Doe
                      </p>
                    </div>
                  </Grid>
                </div>
              </div>
            </div> */}
              <div className="flex w-full my-4">
                <p className="text-[10px] mr-3 font-Regular">
                  PRIMARY CONTACT DETAILS
                </p>
                <hr className="self-center border-[#999999] w-[40%]" />
              </div>
              <div className="flex mb-4">
                <img
                  src={name}
                  className="mr-3 bg-Onyx rounded-[14px]"
                  alt="Name"
                />
                <div>
                  <p className="text-sm font-Regular">Name</p>
                  <p className="text-base font-semibold ">
                    {servicerDetails?.firstName} {servicerDetails?.lastName}
                  </p>
                </div>
              </div>
              <div className="flex mb-4">
                <img
                  src={email}
                  className="mr-3 bg-Onyx rounded-[14px]"
                  alt="email"
                />
                <div>
                  <p className="text-sm font-Regular">
                    Email
                  </p>
                  <p className="text-base font-semibold break-words">
                    {servicerDetails?.email}
                  </p>
                </div>
              </div>
              <div className="flex mb-4">
                <img
                  src={phone}
                  className="mr-3 bg-Onyx rounded-[14px]"
                  alt="name"
                />
                <div>
                  <p className="text-sm font-Regular">
                    Phone Number
                  </p>
                  <p className="text-base font-semibold ">
                    +1 {formatPhoneNumber(servicerDetails?.phoneNumber)}
                  </p>
                </div>
              </div>
              <Grid className="mt-5">
                <div className="col-span-6 ">
                  <div className="bg-[#2A2A2A] self-center px-4 py-6 rounded-xl">
                    <p className="text-white text-lg !font-[600]">
                      {servicerDetails?.claimData?.numberOfClaims ?? 0}
                    </p>
                    <p className="text-neutral-grey text-sm font-Regular">
                      Total number of Claims
                    </p>
                  </div>
                </div>
                <div className="col-span-6 ">
                  <div className="bg-[#2A2A2A] self-center px-4 py-6 rounded-xl">
                    <p className="text-white text-lg  !font-[600]">
                      $
                      {formatOrderValue(
                        servicerDetails?.claimData?.valueClaim ?? parseInt(0)
                      )}
                    </p>
                    <p className="text-neutral-grey text-sm font-Regular">
                      Total Value of Claims
                    </p>
                  </div>
                </div>
              </Grid>
            </SingleView>
          </div>
          <div className="col-span-3 max-h-[85vh] pr-3 overflow-y-scroll">
            <Grid className="">
              <div className="col-span-11">
                <div className="rounded-[30px] p-3 border-[1px] border-Light-Grey">
                  <Grid className="!grid-cols-6 !gap-1">
                    {tabs.map((tab) =>
                      activeTab === tab.id ? (
                        <ActiveTabButton key={tab.id} tab={tab} onClick={() => handleTabClick(tab.id)} />
                      ) : (
                        <InactiveTabButton key={tab.id} tab={tab} onClick={() => handleTabClick(tab.id)} />
                      )
                    )}
                  </Grid>
                </div>
              </div>
              <div className="col-span-1">
                {activeTab !== "Unpaid Claims" &&
                  activeTab !== "Paid Claims" &&
                  activeTab !== "Settings" &&
                  activeTab !== "Claims" ? (
                  <InActiveButton
                    onClick={() => routeToPage(activeTab)}
                    className="flex self-center h-full  mb-4 rounded-xl ml-auto border-[1px] border-Light-Grey"
                  >
                    {" "}
                    <div
                      style={{
                        maskImage: `url(${AddItem})`,
                        WebkitMaskImage: `url(${AddItem})`,
                        maskRepeat: "no-repeat",
                        WebkitMaskRepeat: "no-repeat",
                        maskPosition: "center",
                        WebkitMaskPosition: "center",
                        maskSize: "contain",
                        WebkitMaskSize: "contain",
                      }}
                      className="self-center pr-1 py-1 h-4 w-4"
                    />
                    <span
                      style={{
                        borderLeftWidth: "1px",
                        paddingLeft: "7px",
                      }}
                      className=" ml-1 text-[13px] self-center font-Regular !font-[700]"
                    >
                      Add {activeTab}
                    </span>{" "}
                  </InActiveButton>
                ) : (
                  <></>
                )}
              </div>
            </Grid>

            {tabs.map((tab) => (
              <div
                key={tab.id}
                className={`${activeTab !== tab.id ? "hidden" : "pb-20"}`}
              >
                {tab.content}
              </div>
            ))}
          </div>
        </Grid>
        {/* user popup */}
        <Modal isOpen={isUserModalOpen} onClose={closeUserModal}>
          {userLoader ?
            <div className=" h-[400px] w-full flex py-5">
              <div className="self-center mx-auto">
                <RotateLoader color="#333" />
              </div>
            </div> :
            <div className="py-3">
              <p className="text-center text-3xl mb-5 mt-2 font-bold">
                Add New User
              </p>
              <form onSubmit={userValues.handleSubmit}>
                <Grid className="px-8">
                  <div className="col-span-6">
                    <Input
                      type="text"
                      name="firstName"
                      label="First Name"
                      required={true}
                      placeholder=""
                      className="!bg-white"
                      maxLength={"30"}
                      value={userValues.values.firstName}
                      onBlur={userValues.handleBlur}
                      onChange={userValues.handleChange}
                      error={
                        userValues.touched.firstName &&
                        userValues.errors.firstName
                      }
                    />
                    {userValues.touched.firstName &&
                      userValues.errors.firstName && (
                        <div className="text-red-500 text-sm pl-2 pt-2">
                          {userValues.errors.firstName}
                        </div>
                      )}
                  </div>
                  <div className="col-span-6">
                    <Input
                      type="text"
                      name="lastName"
                      label="Last Name"
                      required={true}
                      placeholder=""
                      className="!bg-white"
                      maxLength={"30"}
                      value={userValues.values.lastName}
                      onBlur={userValues.handleBlur}
                      onChange={userValues.handleChange}
                      error={
                        userValues.touched.lastName && userValues.errors.lastName
                      }
                    />
                    {userValues.touched.lastName &&
                      userValues.errors.lastName && (
                        <div className="text-red-500 text-sm pl-2 pt-2">
                          {userValues.errors.lastName}
                        </div>
                      )}
                  </div>
                  <div className="col-span-6">
                    <Input
                      type="text"
                      name="email"
                      label="Email"
                      placeholder=""
                      className="!bg-white"
                      required={true}
                      value={userValues.values.email}
                      onBlur={userValues.handleBlur}
                      onChange={userValues.handleChange}
                      error={userValues.touched.email && userValues.errors.email}
                    />
                    {userValues.touched.email && userValues.errors.email && (
                      <div className="text-red-500 text-sm pl-2 pt-2">
                        {userValues.errors.email}
                      </div>
                    )}
                  </div>
                  <div className="col-span-6">
                    <Input
                      type="tel"
                      name="phoneNumber"
                      label="Phone"
                      required={true}
                      nonumber={true}
                      className="!bg-white"
                      placeholder=""
                      value={userValues.values.phoneNumber}
                      onChange={(e) => {
                        const sanitizedValue = e.target.value.replace(
                          /[^0-9]/g,
                          ""
                        );
                        console.log(sanitizedValue);
                        userValues.handleChange({
                          target: {
                            name: "phoneNumber",
                            value: sanitizedValue,
                          },
                        });
                      }}
                      onBlur={userValues.handleBlur}
                      minLength={"10"}
                      maxLength={"10"}
                      error={
                        userValues.touched.phoneNumber &&
                        userValues.errors.phoneNumber
                      }
                    />
                    {(userValues.touched.phoneNumber ||
                      userValues.submitCount > 0) &&
                      userValues.errors.phoneNumber && (
                        <div className="text-red-500 text-sm pl-2 pt-2">
                          {userValues.errors.phoneNumber}
                        </div>
                      )}
                  </div>
                  <div className="col-span-6">
                    <Input
                      type="text"
                      name="position"
                      label="Position"
                      className="!bg-white"
                      placeholder=""
                      maxLength={"50"}
                      value={userValues.values.position}
                      onBlur={userValues.handleBlur}
                      onChange={userValues.handleChange}
                      error={
                        userValues.touched.position && userValues.errors.position
                      }
                    />
                  </div>
                  <div className="col-span-6">
                    <p className="flex text-[12px] font-semibold mt-3 mb-6">
                      Do you want to create an account?
                      <RadioButton
                        id="yes-create-account"
                        label="Yes"
                        value="yes"
                        disabled={createAccount === false}
                        checked={createAccountOption === "yes"}
                        onChange={handleRadioChange}
                      />
                      <RadioButton
                        id="no-create-account"
                        label="No"
                        value="no"
                        disabled={createAccount === false}
                        checked={createAccountOption === "no"}
                        onChange={handleRadioChange}
                      />
                    </p>
                  </div>
                </Grid>
                <Grid className="drop-shadow-5xl px-8">
                  <div className="col-span-4">
                    <InActiveButton
                      type="button"
                      className="border w-full !text-sm !font-Regular"
                      onClick={closeUserModal}
                    >
                      Cancel
                    </InActiveButton>
                  </div>
                  <div className="col-span-8">
                    <Button type="submit" className="w-full">
                      Submit
                    </Button>
                  </div>
                </Grid>
              </form>
            </div>
          }
        </Modal>

        {/* <div className="col-span-12">
              <div className="flex w-full my-2">
                <p className="text-sm mr-3 text-neutral-grey font-Regular">
                  BANK DETAILS
                </p>
                <hr className="self-center border-[#999999] w-[80%]" />
              </div>
            </div>
            <div className="col-span-6">
              <Input
                name="bankName"
                type="text"
                className="!bg-white"
                label="Bank Name"
              />
            </div>
            <div className="col-span-6">
              <Input
                name="routingNumber"
                type="number"
                className="!bg-white"
                label="ABA Routing Number"
              />
            </div>
            <div className="col-span-6">
              <Input
                name="accountNumber"
                type="number"
                className="!bg-white"
                label="Account Number"
              />
            </div>
            <div className="col-span-6">
              <Input
                name="accountHolder"
                type="text"
                className="!bg-white"
                label="Account Holder"
              />
            </div> */}
        {/* Modal Email Popop */}
        <Modal isOpen={isModalOpen} onClose={closeModal}>
          <div className=" px-8 py-4">
            <p className="text-3xl text-center font-bold mb-8">
              Edit Servicer Details
            </p>
            <form className="mt-8" onSubmit={formik.handleSubmit}>
              <Grid>
                <div className="col-span-12">
                  <Input
                    type="text"
                    name="name"
                    className="!bg-white"
                    label="Account Name"
                    required={true}
                    placeholder=""
                    maxLength={"500"}
                    value={formik.values.name}
                    onBlur={formik.handleBlur}
                    onChange={formik.handleChange}
                    error={formik.touched.name && formik.errors.name}
                  />
                  {formik.touched.name && formik.errors.name && (
                    <div className="text-red-500 text-sm pl-2 pt-2">
                      {formik.errors.name}
                    </div>
                  )}
                </div>
                <div className="col-span-12">
                  <Input
                    type="text"
                    name="street"
                    className="!bg-white"
                    label="Street Address"
                    required={true}
                    placeholder=""
                    maxLength={"500"}
                    value={formik.values.street}
                    onBlur={formik.handleBlur}
                    onChange={formik.handleChange}
                    error={formik.touched.street && formik.errors.street}
                  />
                  {formik.touched.street && formik.errors.street && (
                    <div className="text-red-500 text-sm pl-2 pt-2">
                      {formik.errors.street}
                    </div>
                  )}
                </div>
                <div className="col-span-6">
                  <Input
                    type="number"
                    name="zip"
                    label="Zip Code"
                    className="!bg-white"
                    required={true}
                    placeholder=""
                    value={formik.values.zip}
                    onChange={formik.handleChange}
                    onBlur={formik.handleBlur}
                    minLength={"5"}
                    maxLength={"6"}
                    error={formik.touched.zip && formik.errors.zip}
                  />
                  {formik.touched.zip && formik.errors.zip && (
                    <div className="text-red-500 text-sm pl-2 pt-2">
                      {formik.errors.zip}
                    </div>
                  )}
                </div>
                <div className="col-span-6">
                  <Input
                    type="text"
                    name="city"
                    label="City"
                    className="!bg-white"
                    placeholder=" "
                    required={true}
                    maxLength={"20"}
                    value={formik.values.city}
                    onChange={formik.handleChange}
                    onBlur={formik.handleBlur}
                    error={formik.touched.city && formik.errors.city}
                  />
                  {formik.touched.city && formik.errors.city && (
                    <div className="text-red-500 text-sm pl-2 pt-2">
                      {formik.errors.city}
                    </div>
                  )}
                </div>
                <div className="col-span-6">
                  <Select
                    label="State"
                    name="state"
                    placeholder=""
                    className="!bg-white"
                    required={true}
                    onChange={handleSelectChange}
                    options={state}
                    value={formik.values.state}
                    onBlur={formik.handleBlur}
                    error={formik.touched.state && formik.errors.state}
                  />
                  {formik.touched.state && formik.errors.state && (
                    <div className="text-red-500 text-sm pl-2 pt-2">
                      {formik.errors.state}
                    </div>
                  )}
                </div>
                <div className="col-span-6">
                  <Input
                    type="text"
                    name="country"
                    label="Country"
                    required={true}
                    placeholder=""
                    className="!bg-[white]"
                    value={formik.values.country}
                    onChange={formik.handleChange}
                    onBlur={formik.handleBlur}
                    defaultValue="USA"
                    error={formik.touched.country && formik.errors.country}
                    disabled
                  />
                </div>
                <div className="col-span-12">
                  <p className="flex text-[11px] mb-3 mt-2 font-semibold ">
                    Do you want to create an account?
                    <RadioButton
                      id="yes-create-account"
                      label="Yes"
                      value={true}
                      checked={createAccount === true}
                      onChange={handleAccountChange}
                    />
                    <RadioButton
                      id="no-create-account"
                      label="No"
                      value={false}
                      checked={createAccount === false}
                      onChange={handleAccountChange}
                    />
                  </p>
                </div>
                <div className="col-span-4">
                  <InActiveButton
                    type="button"
                    className="border w-full !text-sm !font-Regular"
                    onClick={closeModal}
                  >
                    Cancel
                  </InActiveButton>
                </div>
                <div className="col-span-8">
                  <Button type="submit" className="w-full">
                    Submit
                  </Button>
                </div>
              </Grid>
            </form>
          </div>
        </Modal>
        {/* Modal Primary Popop */}
        <Modal isOpen={isModalOpen1} onClose={closeModal1}>
          <form onSubmit={dealerForm.handleSubmit}>
            <div className="text-center py-3">
              <p className="text-3xl mb-0 mt-2 font-bold">
                Assign Dealer
              </p>
              <div className="my-4 h-[350px] max-h-[350px] overflow-y-scroll">
                <DataTable
                  columns={columns}
                  data={dealerList}
                  highlightOnHover
                  sortIcon={
                    <>
                      {" "}
                      <div
                        style={{
                          maskImage: `url(${shorting})`,
                          WebkitMaskImage: `url(${shorting})`,
                          maskRepeat: "no-repeat",
                          WebkitMaskRepeat: "no-repeat",
                          maskPosition: "center",
                          WebkitMaskPosition: "center",
                          maskSize: "contain",
                          WebkitMaskSize: "contain",
                        }}
                        className="ml-2 tabless"
                      />
                      {/* <img src={shorting} className="ml-2" alt="shorting" /> */}
                    </>
                  }
                  noDataComponent={<CustomNoDataComponent />}
                />
              </div>
              <Grid className="drop-shadow-5xl">
                <div className="col-span-4">
                  <InActiveButton
                    type="button"
                    className="border w-full  !text-sm !font-Regular"
                    onClick={closeModal1}
                  >
                    Cancel
                  </InActiveButton>
                </div>
                <div className="col-span-8">
                  <Button type="submit" className="w-full">
                    Submit
                  </Button>
                </div>
              </Grid>
            </div>
          </form>
        </Modal>
        <Modal isOpen={modalOpen} onClose={closeModal10}>
          <div className="text-center py-3">
            <img src={Primary} alt="email Image" className="mx-auto" />
            <p className="text-3xl mb-0 mt-2 font-bold">
              {firstMessage}
            </p>
            <p className=" text-base font-medium mt-4">
              {secondMessage} {""} <br /> Redirecting Back to Detail page in{" "}
              {timer} Seconds
            </p>
          </div>
        </Modal>
      </div>
    </>
  );
}

export default ServicerDetails;
