import React, { useState, useEffect } from "react";
import Button from "../../../common/button";
import Grid from "../../../common/grid";
import Input from "../../../common/input";

// Media Includes
import Search from "../../../assets/images/icons/SearchIcon.svg";
import AddItem from "../../../assets/images/icons/addItem.svg";
import Cross from "../../../assets/images/Cross.png";
import view from "../../../assets/images/whiteView.png";
import Edit from "../../../assets/images/Dealer/EditIcon.svg";
import clearFilter from "../../../assets/images/icons/Clear-Filter-Icon-White.svg";
import Headbar from "../../../common/headBar";
import { Link, useLocation, useNavigate } from "react-router-dom";
import Modal from "../../../common/model";
import Select from "../../../common/select";
import { getAllContractsForAdmin } from "../../../services/orderServices";
import { format } from "date-fns";
import { RotateLoader } from "react-spinners";
import * as Yup from "yup";
import CustomPagination from "../../pagination";
import {
  getAllContractsForCustomerPortal,
  getContractByIdCustomerPortal,
} from "../../../services/dealerServices/orderListServices";
import { useFormik } from "formik";
import CommonTooltip from "../../../common/toolTip";
import SingleView from "../../../common/singleView";
import InActiveButton from "../../../common/inActiveButton";
import Card from "../../../common/card";
import { exportDataForContract } from "../../../services/claimServices";
function CustomerContractList(props) {
  const location = useLocation();
  const [contractDetails, setContractDetails] = useState({});
  const [showTooltip, setShowTooltip] = useState(false);
  const [isDisapprovedOpen, setIsDisapprovedOpen] = useState(false);
  const [contractList, setContractList] = useState([]);
  const [value, setValue] = useState(null);
  const [totalRecords, setTotalRecords] = useState(0);
  const [isViewOpen, setIsViewOpen] = useState(false);
  const [isReportOpen, setIsReportOpen] = useState(false);
  const [viewLoader, setViewLoader] = useState(false);
  const [reportSuccess, setreportSuccess] = useState(false);
  const [pageValue, setPageValue] = useState(1);
  const [selectedProduct, setSelectedProduct] = useState(location.pathname.includes('/orderDetails') ? '' : 'Active');
  const [recordsPerPage, setRecordsPerPage] = useState(10);
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const closeDisapproved = () => {
    setIsDisapprovedOpen(false);
  };
  const closeView = () => {
    setIsViewOpen(false);
  };

  const handleSelectChange1 = (label, value) => {
    console.log(label, value, "selected");
    formik.setFieldValue("status", value);
    setSelectedProduct(value);
  };
  const openView = (id) => {
    setIsViewOpen(true);
    getContractDetails(id);
  };
  const openDisapproved = () => {
    setIsDisapprovedOpen(true);
  };
  const validationSchema = Yup.object().shape({});
  const oneYearAgo = new Date();
  oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1); // Move back 1 year
  oneYearAgo.setDate(oneYearAgo.getDate() + 1);
  console.log(oneYearAgo, 'days-----')
  const capitalizedFlag = props.flag
    ? props.flag.charAt(0).toUpperCase() + props.flag.slice(1)
    : '';
  const today = new Date();
  const initialValues = {
    orderId: "",
    venderOrder: "",
    contractId: "",
    dealerName: "",
    customerName: "",
    servicerName: "",
    manufacture: "",
    model: "",
    serial: "",
    productName: "",
    eligibilty: "",
    dealerSku: "",
    status: props.flag === 'contracts' ? selectedProduct : selectedProduct,
    startDate: oneYearAgo.toISOString().split("T")[0],
    endDate: today.toISOString().split("T")[0],
    userId: props.id,
    flag: capitalizedFlag
  };

  const formik = useFormik({
    initialValues,
    validationSchema,
    onSubmit: (values) => {
      getContracts(1, 10);
      console.log(values);
      setIsDisapprovedOpen(false);
    },
  });

  const getContractDetails = async (id) => {
    setLoading(true);
    const result = await getContractByIdCustomerPortal(id);
    setContractDetails(result.result);
    setLoading(false);
    console.log("by ID -------------------", result);
  };

  const formatOrderValue = (orderValue) => {
    if (Math.abs(orderValue) >= 1e6) {
      return (orderValue / 1e6).toFixed(2) + "M";
    } else {
      return orderValue.toLocaleString(undefined, {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      });
    }
  };

  const getContracts = async (page = 1, rowsPerPage = 10) => {
    setLoading(true);
    setPageValue(page);
    let data = {
      page: page,
      pageLimit: rowsPerPage,
      ...formik.values,
    };
    const result = await getAllContractsForCustomerPortal(data);
    setContractList(result.result);
    console.log(result);
    setTotalRecords(result?.totalCount);
    setLoading(false);
  };

  useEffect(() => {
    getContracts();
  }, []);

  const findDate = (data, index, type) => {
    if (contractList) {
      let foundDate = "Date Not Found";

      contractList.forEach((contract) => {
        const productsArray = contract?.order?.productsArray;

        if (productsArray) {
          const matchingProduct = productsArray.find(
            (product) => product._id === data.orderProductId
          );
          console.log(productsArray);
          if (matchingProduct) {
            foundDate = format(
              new Date(
                type === "start"
                  ? matchingProduct.coverageStartDate1
                  : matchingProduct.coverageEndDate1
              ),
              "MM/dd/yyyy"
            );
          }
        }
      });

      return foundDate;
    }

    return "Date Not Found";
  };

  const handleSelectChange2 = (label, value) => {
    formik.setFieldValue("eligibilty", value);
    setValue(value);
  };
  const handleFilterIconClick = () => {
    formik.resetForm();
    console.log(formik.values);
    setSelectedProduct("");
    // getContract();
  };
  const handlePageChange = async (page, rowsPerPage) => {
    console.log(page, rowsPerPage);
    setLoading(true);
    try {
      await getContracts(page, rowsPerPage);
      setLoading(false);
    } finally {
      setLoading(false);
    }
  };
  const status = [
    { label: "Active", value: "Active" },
    { label: "Waiting", value: "Waiting" },
    { label: "Expired", value: "Expired" },
  ];
  const Eligible = [
    { label: "Eligible", value: true },
    { label: "Not Eligible", value: false },
  ];

  const openReport = () => {
    fileGenrateForm.resetForm();
    setIsReportOpen(true);
  }

  const closeReport = () => {
    setIsReportOpen(false)
  }

  const fileGenrateForm = useFormik({
    initialValues: {
      reportName: '',
      remark: '',
      category: 'contractReporting',
    }, validationSchema: Yup.object({
      reportName: Yup.string().required('Report name is required'),
    }),
    onSubmit: async (values, { setSubmitting }) => {
      console.log(values, formik.values);
      try {
        setViewLoader(true);
        // Combine values from both forms
        setTimeout(() => {
          setreportSuccess(true)
          setViewLoader(false);
          setSubmitting(false);

        }, 2000);
        const data = await exportDataForContract({ ...values, ...formik.values });

        // if (data.code === 200) {
        //   setreportSuccess(true);
        // }
      } catch (error) {
        console.error('Error exporting data:', error);
      } finally {
        // setViewLoader(false);

        // setSubmitting(false);
      }
    }
  });

  return (
    <>
      <div className="mb-8 ml-3">
        <Headbar />

        <div className="flex mt-2">
          <div className="pl-3">
            <p className="font-bold text-[36px] leading-9	mb-[3px]">Contracts</p>
            <ul className="flex self-center">
              <li className="text-sm font-Regular">
                <Link to={"/"}>Home /</Link>{" "}
              </li>
              <li className="text-sm font-semibold ml-1">
                Contracts List
              </li>
            </ul>
          </div>
        </div>

        <Card className="mt-6 border-[1px] border-Light-Grey rounded-xl">
          <Grid className="!p-[26px] !pt-[14px] !pb-0">
            <div className="col-span-3 self-center">
              <p className="text-xl font-semibold">Contracts List</p>
            </div>
            <div className="col-span-9">
              <form onSubmit={formik.handleSubmit}>
                <div className="bg-grayf9 rounded-[30px] p-3 border-[1px] border-Light-Grey">
                  <Grid
                    className={`${props.orderId == null ? "!grid-cols-9" : "!grid-cols-7"
                      }`}
                  >
                    <div className="col-span-2 self-center">
                      <Input
                        type="text"
                        className="!text-[14px] !bg-White-Smoke"
                        className1="!text-[13px] !pt-1 placeholder-opacity-50 !pb-1 placeholder-Black-Russian !bg-[white]"
                        label=""
                        placeholder="Contract ID"
                        name="contractId"
                        {...formik.getFieldProps("contractId")}
                      />
                    </div>
                    {props.orderId == null && (
                      <div className="col-span-2 self-center">
                        <Input
                          name="orderId"
                          type="text"
                          className="!text-[14px] !bg-White-Smoke"
                          className1="!text-[13px] !pt-1 placeholder-opacity-50 !pb-1 placeholder-Black-Russian !bg-[white]"
                          label=""
                          placeholder=" Order ID"
                          {...formik.getFieldProps("orderId")}
                        />
                      </div>
                    )}

                    <div className="col-span-2 self-center">
                      <Input
                        name="venderOrder"
                        type="text"
                        className="!text-[14px] !bg-White-Smoke"
                        className1="!text-[13px] !pt-1 placeholder-opacity-50 !pb-1 placeholder-Black-Russian !bg-[white]"
                        label=""
                        placeholder="Dealer P.O. #"
                        {...formik.getFieldProps("venderOrder")}
                      />
                    </div>
                    <div className="col-span-1 self-center flex justify-center">
                      <Button type="submit" className="!p-2">
                        <img
                          src={Search}
                          className="cursor-pointer "
                          alt="Search"
                        />
                      </Button>
                      <InActiveButton
                        type="submit"
                        onClick={() => {
                          handleFilterIconClick();
                        }}
                      >
                        <div
                          style={{
                            maskImage: `url(${clearFilter})`,
                            WebkitMaskImage: `url(${clearFilter})`,
                            maskRepeat: "no-repeat",
                            WebkitMaskRepeat: "no-repeat",
                            maskPosition: "center",
                            WebkitMaskPosition: "center",
                            maskSize: "contain",
                            WebkitMaskSize: "contain",
                          }}
                          className="self-center pr-1 py-1 h-4 w-4 cursor-pointer mx-auto"
                        />
                      </InActiveButton>
                    </div>
                    <div
                      className={`${props.orderId == null ? "" : "text-center"
                        } col-span-2 self-center`}
                    >
                      <Button
                        className="!text-[13px]"
                        onClick={() => openDisapproved()}
                      >
                        Advance Search
                      </Button>
                    </div>
                  </Grid>
                </div>
              </form>
            </div>
          </Grid>
          {loading ? (
            <div className=" h-[400px] w-full flex py-5">
              <div className="self-center mx-auto">
                <RotateLoader color="#333" />
              </div>
            </div>
          ) : (
            <>
              {contractList?.result?.length !== 0 &&
                <div className="text-right mt-5">
                  <Button className='!text-sm' onClick={openReport}>Generate Report</Button>
                  <Button className='!text-sm !ml-3'> <Link to={window.location.pathname.includes("/customer/claimList") ? '/customer/Reporting/List' : '/Reporting/List'}> View Report </Link> </Button>
                </div>}
              {contractList &&
                contractList.map((res, index) => {
                  return (
                    <div className="px-3 mt-5">
                      <div>
                        <SingleView className='rounded-t-xl'>
                          <Grid className="!gap-2 !grid-cols-11">
                            <div className="col-span-3 self-center text-center bg-contract bg-cover bg-right bg-no-repeat rounded-ss-xl">
                              <p className="py-2 font-Regular">
                                Contract ID : <b> {res.unique_key} </b>
                              </p>
                            </div>
                            <div className="col-span-3 self-center text-center bg-contract bg-cover bg-right bg-no-repeat ">
                              <p className="py-2 font-Regular">
                                Order ID : <b> {res?.orderUniqueKey} </b>
                              </p>
                            </div>
                            <div className="col-span-3 self-center text-center bg-contract bg-cover bg-right bg-no-repeat ">
                              <p className="py-2 font-Regular">
                                Dealer P.O. # : <b> {res?.venderOrder} </b>
                              </p>
                            </div>
                            <div className="col-span-1 self-center justify-end"></div>
                            <div className="col-span-1 self-center ">
                              <div
                                onClick={() => openView(res._id)}
                                className="self-center ml-auto bg-[#464646] w-[38%] rounded-full cursor-pointer mr-2 p-1 text-center"
                              >
                                {" "}
                                <img
                                  src={view}
                                  className="mx-auto  w-[23px] h-[23px] "
                                  alt="edit"
                                />{" "}
                              </div>
                            </div>
                          </Grid>
                        </SingleView>
                        <Grid className="!gap-0 !grid-cols-5 mb-5">
                          <div className="col-span-1 border border-Light-Grey">
                            <div className="py-4 px-3">
                              <p className="font-bold text-sm font-Regular">
                                Manufacturer
                              </p>
                              <p className=" text-base font-semibold">
                                {res.manufacture}
                              </p>
                            </div>
                          </div>
                          <div className="col-span-1 border border-Light-Grey">
                            <div className="py-4 px-3">
                              <p className="font-bold text-sm font-Regular">
                                Model
                              </p>
                              <p className=" text-base font-semibold">
                                {res.model}
                              </p>
                            </div>
                          </div>
                          <div className="col-span-1 border border-Light-Grey">
                            <div className="py-4 px-3">
                              <p className="font-bold text-sm font-Regular">
                                Serial # / Device ID
                              </p>
                              <p className=" text-base font-semibold break-words">
                                {res.serial}
                              </p>
                            </div>
                          </div>
                          <div className="col-span-1 border border-Light-Grey">
                            <div className="py-4 px-3">
                              <p className="font-bold text-sm font-Regular">
                                Status
                              </p>
                              <p className=" text-base font-semibold">
                                {res.status}
                              </p>
                            </div>
                          </div>
                          <div className="col-span-1 border border-Light-Grey rounded-ee-xl">
                            <div className="py-4 px-3">
                              <p className="font-bold text-sm font-Regular">
                                Eligibility
                              </p>
                              {res?.eligibilty === false ? (
                                <>
                                  <CommonTooltip
                                    place="left"
                                    id={`tooltip-${index}`}
                                    content={res?.reason}
                                  >
                                    <p className=" cursor-pointer text-base font-semibold">
                                      Not Eligible
                                    </p>
                                  </CommonTooltip>
                                </>
                              ) : (
                                <p className=" text-base font-semibold">
                                  Eligible
                                </p>
                              )}
                            </div>
                          </div>
                        </Grid>
                      </div>
                    </div>
                  );
                })}
            </>
          )}
          {totalRecords == 0 && !loading ? (
            <div className="text-center my-5">
              <p>No records found</p>
            </div>
          ) : (
            <CustomPagination
              totalRecords={totalRecords}
              page={pageValue}
              className={loading ? "opacity-0" : "opacity-100"}
              rowsPerPageOptions={[10, 20, 50, 100]}
              onPageChange={handlePageChange}
              setRecordsPerPage={setRecordsPerPage}
            />
          )}
          <Modal isOpen={isDisapprovedOpen} onClose={closeDisapproved}>
            <Button
              onClick={closeDisapproved}
              className="absolute right-[-13px] top-0 h-[80px] w-[80px] !p-[19px] mt-[-9px] !rounded-full !bg-Granite-Gray"
            >
              <img
                src={Cross}
                className="w-full h-full text-black rounded-full p-0"
              />
            </Button>
            <div className="py-3">
              <form onSubmit={formik.handleSubmit}>
                <div className="py-3">
                  <p className="text-center text-3xl font-semibold ">
                    Advance Search
                  </p>
                  <Grid className="mt-5 px-6">
                    <div className="col-span-6">
                      <Input
                        type="text"
                        name="contractId"
                        className="!bg-white"
                        label="Contract ID"
                        placeholder=""
                        {...formik.getFieldProps("contractId")}
                      />
                    </div>
                    {props.orderId == null ? (
                      <>
                        <div className="col-span-6">
                          <Input
                            type="text"
                            name="orderId"
                            className="!bg-white"
                            label="Order ID"
                            {...formik.getFieldProps("orderId")}
                            placeholder=""
                          />
                        </div>
                        <div className="col-span-6">
                          <Input
                            type="text"
                            name="venderOrder"
                            className="!bg-white"
                            label="Dealer P.O. #"
                            {...formik.getFieldProps("venderOrder")}
                            placeholder=""
                          />
                        </div>
                      </>
                    ) : (
                      ""
                    )}

                    <div className="col-span-6">
                      <Input
                        type="text"
                        name="serial"
                        className="!bg-white"
                        label="Serial # / Device ID"
                        placeholder=""
                        {...formik.getFieldProps("serial")}
                      />
                    </div>
                    <div className="col-span-6">
                      <Input
                        type="text"
                        name="productName"
                        className="!bg-white"
                        label="Product Name"
                        placeholder=""
                        {...formik.getFieldProps("productName")}
                      />
                    </div>
                    <div className="col-span-6">
                      <Input
                        type="text"
                        name="dealerSku"
                        className="!bg-white"
                        label="Dealer SKU"
                        placeholder=""
                        {...formik.getFieldProps("dealerSku")}
                      />
                    </div>
                    <div className="col-span-6">
                      <Input
                        type="text"
                        name="servicerName"
                        className="!bg-white"
                        label="Servicer Name"
                        {...formik.getFieldProps("servicerName")}
                        placeholder=""
                      />
                    </div>

                    <div className="col-span-6">
                      <Input
                        type="text"
                        name="model"
                        className="!bg-white"
                        label="Model"
                        placeholder=""
                        {...formik.getFieldProps("model")}
                      />
                    </div>
                    <div className="col-span-6">
                      <Input
                        type="text"
                        name="manufacture"
                        className="!bg-white"
                        label="Manufacturer"
                        placeholder=""
                        {...formik.getFieldProps("manufacture")}
                      />
                    </div>
                    <div className="col-span-6">
                      <Select
                        label="Status"
                        options={status}
                        color="text-Black-Russian opacity-50"
                        value={selectedProduct}
                        // className1="!pt-1 !pb-1 !text-[13px] !bg-[white]"
                        className="!text-[14px] !bg-white"
                        selectedValue={selectedProduct}
                        onChange={handleSelectChange1}
                      />
                    </div>
                    <div className="col-span-6">
                      <Select
                        label="Eligibility"
                        options={Eligible}
                        color="text-Black-Russian opacity-50"
                        value={value}
                        // className1="!pt-1 !pb-1 !text-[13px] !bg-[white]"
                        className="!text-[14px] !bg-white"
                        selectedValue={value}
                        onChange={handleSelectChange2}
                      />
                    </div>
                    <div className="col-span-6">
                      <Input
                        type="date"
                        name="startDate"
                        className="!bg-white z-10"
                        label="Start Date"
                        placeholder=""
                        min={new Date(new Date().setFullYear(new Date().getFullYear() - 1))
                          .toISOString()
                          .split("T")[0]}
                        maxDate={new Date().toISOString().split("T")[0]}
                        {...formik.getFieldProps("startDate")}
                      />
                    </div>
                    <div className="col-span-6">
                      <Input
                        type="date"
                        name="endDate"
                        className="!bg-white z-10"
                        label="End Date"
                        maxDate={new Date().toISOString().split("T")[0]}
                        placeholder=""
                        {...formik.getFieldProps("endDate")}
                      />
                    </div>
                    <div className="col-span-12">
                      <Button type="submit" className={"w-full"}>
                        Search
                      </Button>
                    </div>
                  </Grid>
                </div>
              </form>
            </div>
          </Modal>
        </Card>
      </div >
      <Modal isOpen={isViewOpen} onClose={closeView} className="!w-[1100px]">
        <Button
          onClick={closeView}
          className={`absolute right-[-13px] top-0 h-[80px] w-[80px] !p-[19px] mt-[-9px] !rounded-full ${props?.orderId == null && props?.flag == undefined
            ? "!bg-gradient-to-t !from-[#4f4f4f] !to-[#616060]"
            : "!bg-Granite-Gray"
            } `}
        >
          <img
            src={Cross}
            className="w-full h-full text-black rounded-full p-0"
          />
        </Button>
        <div className="text-center mt-2">
          <p className="text-3xl font-semibold mb-4">Contract Details </p>
          <div>
            {loading ? (
              <div className=" h-[400px] w-full flex py-5">
                <div className="self-center mx-auto">
                  <RotateLoader color="#333" />
                </div>
              </div>
            ) : (
              <>
                <SingleView className='rounded-t-xl'>
                  <Grid className="!gap-2 !grid-cols-11">
                    <div className="col-span-3 self-center text-left bg-contract bg-contain bg-right bg-no-repeat rounded-ss-xl">
                      <p className="py-2 font-Regular">
                        Contract ID : <b> {contractDetails?.unique_key} </b>
                      </p>
                    </div>
                    <div className="col-span-3 self-center text-left bg-contract bg-contain bg-right bg-no-repeat ">
                      <p className="py-2 font-Regular">
                        Order ID :{" "}
                        <b> {contractDetails?.order?.[0]?.unique_key} </b>
                      </p>
                    </div>
                    <div className="col-span-3 self-center text-left bg-contract bg-contain bg-right bg-no-repeat ">
                      <p className="py-2 font-Regular">
                        Dealer P.O. # :{" "}
                        <b> {contractDetails?.order?.[0]?.venderOrder} </b>
                      </p>
                    </div>
                    <div className="col-span-1"></div>
                    <div className="col-span-1 self-center justify-end"></div>
                  </Grid>
                </SingleView>
                <div className="mb-5 max-h-[70vh] overflow-y-scroll">
                  <Grid className="!gap-0 !grid-cols-5 ">
                    <div className="col-span-1 border border-Light-Grey">
                      <div className="py-4 px-3">
                        <p className="font-bold text-sm font-Regular">
                          Manufacturer
                        </p>
                        <p className=" text-base font-semibold">
                          {contractDetails?.manufacture}
                        </p>
                      </div>
                    </div>
                    <div className="col-span-1 border border-Light-Grey">
                      <div className="py-4 px-3">
                        <p className="font-bold text-sm font-Regular">
                          Model
                        </p>
                        <p className=" text-base font-semibold">
                          {contractDetails?.model}
                        </p>
                      </div>
                    </div>
                    <div className="col-span-1 border border-Light-Grey">
                      <div className="py-4 px-3">
                        <p className=" text-sm font-bold">
                          Serial # / Device ID
                        </p>
                        <p className=" text-base font-semibold break-words">
                          {contractDetails?.serial}
                        </p>
                      </div>
                    </div>
                    <div className="col-span-1 border border-Light-Grey ">
                      <div className="py-4 px-3">
                        <p className="font-bold text-sm font-Regular">
                          Condition
                        </p>
                        <p className=" text-base font-semibold">
                          {contractDetails?.condition}
                        </p>
                      </div>
                    </div>
                    <div className="col-span-1 border border-Light-Grey">
                      <div className="py-4 px-3">
                        <p className="font-bold text-sm font-Regular">
                          Servicer Name
                        </p>
                        <p className=" text-base font-semibold">
                          {contractDetails?.order?.[0]?.servicer?.[0]?.name}
                        </p>
                      </div>
                    </div>
                    <div className="col-span-1 border border-Light-Grey">
                      <div className="py-4 px-3">
                        <p className="font-bold text-sm font-Regular">
                          Status
                        </p>
                        <p className=" text-base font-semibold">
                          {contractDetails?.status}
                        </p>
                      </div>
                    </div>
                    <div className="col-span-1 border border-Light-Grey">
                      <div className="py-4 px-3">
                        <p className="font-bold text-sm font-Regular">
                          Product Category
                        </p>
                        <p className=" text-base font-semibold">
                          {
                            contractDetails?.order?.[0]?.productsArray?.[0]
                              ?.priceBook?.[0].category.name
                          }
                        </p>
                      </div>
                    </div>
                    <div className="col-span-1 border border-Light-Grey">
                      <div className="py-4 px-3">
                        <p className="font-bold text-sm font-Regular">
                          Dealer SKU
                        </p>
                        <p className=" text-base font-semibold">
                          {contractDetails?.dealerSku}
                        </p>
                      </div>
                    </div>
                    <div className="col-span-1 border border-Light-Grey">
                      <div className="py-4 px-3">
                        <p className="font-bold text-sm font-Regular">
                          Product Name
                        </p>
                        <p className=" text-base font-semibold">
                          {contractDetails?.pName}
                        </p>
                      </div>
                    </div>
                    <div className="col-span-2 border border-Light-Grey">
                      <div className="py-4 px-3">
                        <p className="font-bold text-sm font-Regular">
                          Product Description
                        </p>
                        <p className=" text-base font-semibold">
                          {
                            contractDetails?.order?.[0]?.productsArray?.[0]
                              ?.description
                          }
                        </p>
                      </div>
                    </div>
                    <div className="col-span-1 border border-Light-Grey">
                      <div className="py-4 px-3">
                        <p className="font-bold text-sm font-Regular">
                          Price Type
                        </p>
                        <p className=" text-base font-semibold">
                          {
                            contractDetails?.order?.[0]?.productsArray?.[0]
                              ?.priceType
                          }
                        </p>
                      </div>
                    </div>
                    <div className="col-span-1 border border-Light-Grey">
                      <div className="py-4 px-3">
                        <p className="font-bold text-sm font-Regular">
                          Eligibility
                        </p>
                        {/* <p className=" text-base font-semibold">
                            {contractDetails?.eligibilty === true
                              ? "Eligible"
                              : "Not Eligible "}
                          </p> */}
                        {contractDetails?.eligibilty === false ? (
                          <>
                            <CommonTooltip
                              place="left"
                              id={`tooltip`}
                              content={contractDetails?.reason}
                            >
                              <p className=" cursor-pointer text-base font-semibold">
                                Not Eligible
                              </p>
                            </CommonTooltip>
                          </>
                        ) : (
                          <p className=" text-base font-semibold">
                            Eligible
                          </p>
                        )}
                      </div>
                    </div>



                    <div className="col-span-1 border border-Light-Grey ">
                      <div className="py-4 px-3">
                        <p className="font-bold text-sm font-Regular">
                          Coverage Start Date
                        </p>
                        <p className=" text-base font-semibold">
                          {new Date(
                            contractDetails?.order?.[0]?.productsArray?.[0]?.coverageStartDate1
                          ).toLocaleDateString("en-US", {
                            month: "2-digit",
                            day: "2-digit",
                            year: "numeric",
                          })}
                        </p>
                      </div>
                    </div>
                    <div className="col-span-1 border border-Light-Grey rounded-ee-xl">
                      <div className="py-4 px-3">
                        <p className="font-bold text-sm font-Regular">
                          Coverage End Date
                        </p>
                        <p className=" text-base font-semibold">
                          {new Date(
                            contractDetails?.order?.[0]?.productsArray?.[0]?.coverageEndDate1
                          ).toLocaleDateString("en-US", {
                            month: "2-digit",
                            day: "2-digit",
                            year: "numeric",
                          })}
                        </p>
                      </div>
                    </div>
                    <div className="col-span-1 border border-Light-Grey ">
                      <div className="py-4 px-3">
                        <p className="font-bold text-sm font-Regular">
                          Manufacturer Labour Warranty End Date
                        </p>
                        <p className=" text-base font-semibold">
                          {new Date(
                            contractDetails?.labourWarranty
                          ).toLocaleDateString("en-US", {
                            month: "2-digit",
                            day: "2-digit",
                            year: "numeric",
                          })}
                        </p>
                      </div>
                    </div>
                    <div className="col-span-1 border border-Light-Grey ">
                      <div className="py-4 px-3">
                        <p className="font-bold text-sm font-Regular">
                          Manufacturer Parts Warranty End Date
                        </p>
                        <p className=" text-base font-semibold">
                          {new Date(
                            contractDetails?.partsWarranty
                          ).toLocaleDateString("en-US", {
                            month: "2-digit",
                            day: "2-digit",
                            year: "numeric",
                          })}
                        </p>
                      </div>
                    </div>
                    <div className="col-span-1 border border-Light-Grey ">
                      <div className="py-4 px-3">
                        <p className="font-bold text-sm font-Regular">
                          Purchase Date
                        </p>
                        <p className=" text-base font-semibold">
                          {new Date(
                            contractDetails?.purchaseDate
                          ).toLocaleDateString("en-US", {
                            month: "2-digit",
                            day: "2-digit",
                            year: "numeric",
                          })}
                        </p>
                      </div>
                    </div>
                    {contractDetails?.order?.[0]?.productsArray?.[0]?.priceType ==
                      "Quantity Pricing" ? (
                      <>
                        <div className="col-span-5">
                          <table className="w-full border text-center">
                            <tr className="border staticTable">
                              <th colSpan={"3"}>Quantity Pricing List </th>
                            </tr>
                            <tr className="border staticTable">
                              <th className="w-1/3">Name</th>
                              <th className="w-1/3"> Quantity Per Unit</th>
                              <th className="w-1/3"> Quantity</th>
                            </tr>
                            {contractDetails?.order?.[0].productsArray?.[0]
                              ?.QuantityPricing.length !== 0 &&
                              contractDetails?.order?.[0].productsArray?.[0]?.QuantityPricing.map(
                                (item, index) => (
                                  <tr key={index} className="border">
                                    <td>{item.name}</td>
                                    <td>{item.quantity}</td>
                                    <td>{item.enterQuantity}</td>
                                  </tr>
                                )
                              )}
                          </table>
                        </div>
                      </>
                    ) : (
                      ""
                    )}
                  </Grid>
                  <Grid className="!gap-0 ">
                    <div className="col-span-3 border border-Light-Grey pl-4">
                      <p className="text-base mb-2 text-left font-semibold">
                        # of Claims Over the Certain Period
                      </p>
                      <p className="text-[14px] mb-2 text-left font-semibold">

                        {
                          contractDetails?.noOfClaim?.value == "-1"
                            ? ""
                            : `${contractDetails?.noOfClaim?.period} - `
                        }
                        {" "}
                        {contractDetails?.noOfClaim?.value == -1
                          ? "Unlimited"
                          : contractDetails?.noOfClaim?.value}
                      </p>
                    </div>
                    <div className="col-span-3 border border-Light-Grey pl-4">
                      <p className="text-base mb-2 text-left font-semibold">
                        # of Claims in Coverage<br /> Period
                      </p>
                      <p className="text-[14px] text-left font-semibold">
                        {contractDetails?.noOfClaimPerPeriod == -1
                          ? "Unlimited"
                          : contractDetails?.noOfClaimPerPeriod}
                      </p>
                    </div>
                    <div className="col-span-3 border border-Light-Grey pl-4">
                      <p className=" text-base mb-2 text-left font-semibold">
                        {" "}
                        Is manufacturer warranty included?
                      </p>
                      <p className="text-[14px] text-left font-semibold">
                        {contractDetails?.isManufacturerWarranty == true
                          ? "Yes"
                          : "No"}
                      </p>
                    </div>
                    <div className="col-span-3 border border-Light-Grey pl-4">
                      <p className=" text-base mb-2 text-left font-semibold">
                        {" "}
                        Is There a Maximum Claim <br /> Amount ?
                      </p>
                      <p className="text-[14px] text-left font-semibold">
                        {contractDetails?.isMaxClaimAmount == true
                          ? "Yes"
                          : "No"}
                      </p>
                    </div>
                    <div className="col-span-12">
                      <table className="w-full border text-center">
                        <tr className="border staticTable">
                          <th>Coverage Type</th>
                          <th>Waiting Days</th>
                          <th>Deductible</th>
                        </tr>

                        {contractDetails?.mergedData &&
                          contractDetails?.mergedData.length > 0 && (
                            <>
                              {contractDetails?.mergedData.map((type, index) => (
                                <tr key={index} className="border ">
                                  <td className="font-semibold  mx-[19px]">
                                    {type.label}
                                  </td>
                                  <td className="font-semibold mx-[19px]">
                                    {type.waitingDays}
                                  </td>
                                  <td className="font-semibold  mx-[19px]">
                                    {type.amountType != "percentage" && "$"}
                                    {type.amountType === "percentage"
                                      ? type.deductible
                                      : type.deductible === undefined
                                        ? (0).toLocaleString(undefined, {
                                          minimumFractionDigits: 2,
                                        })
                                        : formatOrderValue(type.deductible ?? 0)}
                                    {type.amountType == "percentage" && "%"}
                                  </td>
                                </tr>
                              ))}
                            </>
                          )}
                      </table>
                    </div>
                  </Grid>
                </div>
              </>
            )}
          </div>
        </div>
      </Modal>

      <Modal isOpen={isReportOpen} onClose={closeReport}>
        <Button
          onClick={closeReport}
          className="absolute right-[-13px] top-0 h-[80px] w-[80px] !p-[19px] mt-[-9px] !rounded-full !bg-Granite-Gray"
        >
          <img
            src={Cross}
            className="w-full h-full text-black rounded-full p-0"
          />
        </Button>
        <div className="py-3">
          {viewLoader ? (
            <>
              <div className=" h-[400px] w-full flex py-5">
                <div className="self-center mx-auto">
                  <RotateLoader color="#333" />
                </div>
              </div>
            </>
          ) : (
            !reportSuccess ? (<div>
              <p className="text-center text-3xl font-semibold mb-2 mx-auto">
                Generate Report
              </p>
              <p className="text-center w-2/3 mx-auto mb-5">
                This report will include all contract within the specified date range
                along with key details for your review. Please provide the{" "}
                <b>Report Name</b> and any <b>Remarks</b> in the text fields below
                before proceeding.
              </p>
              <div className="px-8">
                <form onSubmit={fileGenrateForm.handleSubmit}>
                  {/* File Name Field */}
                  <div className="col-span-12">
                    <Input
                      type="text"
                      id="reportName"
                      name="reportName"
                      label='File Name'
                      required={true}
                      value={fileGenrateForm.values.reportName}
                      onChange={fileGenrateForm.handleChange}
                      onBlur={fileGenrateForm.handleBlur}
                      className="!bg-white"
                      placeholder=""
                    />
                    {fileGenrateForm.touched.reportName && fileGenrateForm.errors.reportName && (
                      <div className="text-red-500 text-sm">{fileGenrateForm.errors.reportName}</div>
                    )}
                  </div>

                  {/* Remarks Field */}
                  <div className="col-span-12 mt-4">
                    <div className="relative">
                      <label
                        htmlFor="Remark"
                        className="absolute text-base text-[#5D6E66] leading-6 duration-300 transform origin-[0] top-1 bg-white left-2 px-1 -translate-y-4 scale-75"
                      >
                        Remark
                      </label>
                      <textarea
                        id="remark"
                        name="remark"
                        rows="4"
                        maxLength={150}
                        value={fileGenrateForm.values.remark}
                        onChange={fileGenrateForm.handleChange}
                        onBlur={fileGenrateForm.handleBlur}
                        className="block px-2.5 pb-2.5 pt-4 w-full text-base font-semibold text-light-black bg-transparent rounded-lg border-[1px] border-gray-300 appearance-none peer resize-none	"
                        placeholder=""
                      />
                    </div>
                  </div>

                  {/* Submit Buttons */}
                  <div className="col-span-12 mt-6 flex justify-end">
                    <InActiveButton
                      type="button"
                      className="mr-3 "
                      onClick={closeReport}
                    >
                      Cancel
                    </InActiveButton>
                    <Button
                      type="submit"
                      className=""
                      disabled={fileGenrateForm.isSubmitting}
                    >
                      {fileGenrateForm.isSubmitting ? 'Generating...' : 'Generate'}
                    </Button>
                  </div>
                </form>
              </div>
            </div>) : (
              <>
                <p className="text-center text-3xl font-semibold mb-2 mx-auto">
                  Generate Report
                </p>
                <p className="text-center w-2/3 mx-auto mb-5">
                  Thank you for generating the report. The report is currently being processed. Once ready, you can download it by visiting the reports page from below link.
                </p>
                <div className="text-center">
                  <Link to={window.location.pathname.includes('customer/claimList') ? "/customer/Reporting/List" : "/Reporting/List"} className="text-blue-500 hover:underline">
                    Go to Reports Page
                  </Link>
                </div>
              </>
            )

          )}
        </div>
      </Modal>
    </>
  );
}

export default CustomerContractList;
